// Lets a customer see, change or cancel their own bookings.
// action: list | check_cancel | cancel | check_change | change
// A booking is only found if it belongs to the customer's phone number.
const q = $('When Called by Agent').first().json;
const villas = $('Read Villas').all().map(i => i.json).filter(v => v.Villa_ID);
const bookings = $('Read Bookings').all().map(i => i.json).filter(b => b.Booking_ID);
const s = v => (v === undefined || v === null) ? '' : String(v).trim();
const num = v => { const n = Number(s(v).replace(/[^0-9.]/g, '')); return isNaN(n) ? 0 : n; };
const digits = v => s(v).replace(/[^0-9]/g, '');
const MON = { jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11 };
function day(v) {
  const t = s(v); if (!t) return null;
  let m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if (m) return Date.UTC(+m[1], +m[2]-1, +m[3]);
  m = t.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/); if (m) return Date.UTC(+m[3], +m[2]-1, +m[1]);
  m = t.match(/^(\d{1,2})\s*([A-Za-z]{3})[A-Za-z]*\s*(\d{4})?/); if (m && MON[m[2].toLowerCase()] !== undefined) return Date.UTC(m[3] ? +m[3] : new Date().getUTCFullYear(), MON[m[2].toLowerCase()], +m[1]);
  return null;
}
const iso = d => new Date(d).toISOString().slice(0, 10);
const now = new Date();
const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const action = s(q.action).toLowerCase();
const fail = reason => [{ json: { ok: false, action, reason } }];

const phone = digits(q.contact);
if (phone.length < 10) return fail('the phone number used for the booking is missing');
const mine = bookings.filter(b => digits(b.Customer_WhatsApp).slice(-10) === phone.slice(-10));
const active = mine.filter(b => s(b.Booked).toLowerCase().startsWith('y') && day(b.Check_Out) !== null && day(b.Check_Out) >= today);
const show = b => ({ booking_id: s(b.Booking_ID), villa_name: s(b.Villa_Name), check_in: s(b.Check_In), check_out: s(b.Check_Out), guests: num(b.Guests), nights: num(b.Nights), total_amount_inr: num(b.Total_Amount_INR), payment_status: s(b.Payment_Status) });

if (action === 'list') return [{ json: { ok: true, action, booking_count: active.length, bookings: active.map(show) } }];

const b = active.find(x => s(x.Booking_ID).toUpperCase() === s(q.booking_id).toUpperCase());
if (!b) return fail(active.length ? 'no active booking with that Booking ID for this phone number' : 'no active bookings found for this phone number');
if (day(b.Check_In) <= today) return fail('the stay has already started, so it can only be changed by our team');

if (action === 'check_cancel' || action === 'cancel') {
  const out = { ok: true, action, booking: show(b) };
  if (action === 'cancel') out.update = { Booking_ID: s(b.Booking_ID), Booked: 'no', Payment_Status: 'Cancelled' };
  return [{ json: out }];
}

if (action !== 'check_change' && action !== 'change') return fail('unknown action');
// New values: anything not given stays as it was.
const vid = s(q.new_villa_id) || s(b.Villa_ID);
const ci = day(q.new_check_in) ?? day(b.Check_In);
const co = day(q.new_check_out) ?? day(b.Check_Out);
const guests = num(q.new_guests) || num(b.Guests);
const v = villas.find(x => s(x.Villa_ID).toUpperCase() === vid.toUpperCase());
const problems = [];
let nights = null;
if (ci === null || co === null) problems.push('the new dates are not clear');
else {
  nights = Math.round((co - ci) / 86400000);
  if (nights < 1) problems.push('check-out must be after check-in');
  if (ci < today) problems.push('the new check-in date is in the past');
}
if (!v) problems.push('that villa was not found');
else {
  if (s(v.Booking_Status).toLowerCase() !== 'available') problems.push('the villa is not available for booking');
  if (num(v.Max_Guests) < guests) problems.push('the villa fits only ' + num(v.Max_Guests) + ' guests');
  if (nights >= 1) {
    const af = day(v.Available_From), at = day(v.Available_To);
    if (af !== null && ci < af) problems.push('the villa is only available from ' + iso(af));
    if (at !== null && co > at) problems.push('the villa is only available until ' + iso(at));
    if (nights < num(v.Minimum_Nights)) problems.push('the minimum stay is ' + num(v.Minimum_Nights) + ' nights');
    const clash = bookings.some(o => s(o.Booking_ID) !== s(b.Booking_ID)
      && s(o.Villa_ID).toUpperCase() === s(v.Villa_ID).toUpperCase()
      && s(o.Booked).toLowerCase().startsWith('y')
      && day(o.Check_In) !== null && day(o.Check_Out) !== null
      && day(o.Check_In) < co && day(o.Check_Out) > ci);
    if (clash) problems.push('the villa is already booked for these dates');
  }
}
if (problems.length) return fail(problems.join('; '));
const total = num(v.Nightly_Rate_INR) * nights;
const after = { booking_id: s(b.Booking_ID), villa_name: s(v.Villa_Name), check_in: iso(ci), check_out: iso(co), guests, nights, total_amount_inr: total };
const out = { ok: true, action, before: show(b), after, price_difference_inr: total - num(b.Total_Amount_INR) };
if (action === 'change') out.update = { Booking_ID: s(b.Booking_ID), Villa_ID: s(v.Villa_ID), Villa_Name: s(v.Villa_Name), Check_In: iso(ci), Check_Out: iso(co), Guests: guests, Nights: nights, Total_Amount_INR: total };
return [{ json: out }];

